begin;
create table if not exists public.mme_vendors(vendor_id uuid primary key default gen_random_uuid(),vendor_code text not null unique,vendor_name text not null,status text not null default 'active' check(status in ('active','on_hold','inactive')),website text,phone text,email text,payment_terms text,account_reference text,notes text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_vendor_contacts(contact_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_vendors(vendor_id),contact_name text not null,email text,phone text,role_title text,is_primary boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.mme_purchase_orders(po_id uuid primary key default gen_random_uuid(),po_number text not null unique,vendor_id uuid not null references public.mme_vendors(vendor_id),location_id uuid not null references public.mme_inventory_locations(location_id),status text not null default 'draft' check(status in ('draft','submitted','approved','partially_received','received','cancelled')),currency text not null default 'USD',ordered_at timestamptz,expected_at date,subtotal numeric(14,2) not null default 0 check(subtotal>=0),tax_total numeric(14,2) not null default 0 check(tax_total>=0),shipping_total numeric(14,2) not null default 0 check(shipping_total>=0),notes text,created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_purchase_order_lines(line_id uuid primary key default gen_random_uuid(),po_id uuid not null references public.mme_purchase_orders(po_id),product_id uuid not null references public.mme_inventory_products(product_id),ordered_quantity numeric(14,3) not null check(ordered_quantity>0),received_quantity numeric(14,3) not null default 0 check(received_quantity>=0),unit_cost numeric(14,2) not null check(unit_cost>=0),line_total numeric(14,2) generated always as (ordered_quantity*unit_cost) stored,created_at timestamptz not null default now(),check(received_quantity<=ordered_quantity));
create table if not exists public.mme_vendor_invoices(invoice_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_vendors(vendor_id),po_id uuid references public.mme_purchase_orders(po_id),invoice_number text not null,invoice_date date not null,due_date date,total_amount numeric(14,2) not null check(total_amount>=0),status text not null default 'unpaid' check(status in ('unpaid','under_review','approved','paid','disputed','void')),external_reference text,notes text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(vendor_id,invoice_number));
create table if not exists public.mme_purchase_order_events(event_id uuid primary key default gen_random_uuid(),po_id uuid not null references public.mme_purchase_orders(po_id),event_type text not null,from_status text,to_status text,details jsonb not null default '{}',actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_purchase_orders_vendor_date_idx on public.mme_purchase_orders(vendor_id,created_at desc);
create index if not exists mme_purchase_order_lines_po_idx on public.mme_purchase_order_lines(po_id);
create index if not exists mme_vendor_invoices_due_idx on public.mme_vendor_invoices(due_date,status);
create or replace function public.mme_purchase_order_transition(p_po_id uuid,p_action text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_po public.mme_purchase_orders%rowtype;v_next text; begin select * into v_po from public.mme_purchase_orders where po_id=p_po_id for update; if not found then raise exception 'purchase_order_not_found'; end if; if p_action='submit' and v_po.status='draft' then v_next='submitted'; elsif p_action='approve' and v_po.status='submitted' then v_next='approved'; elsif p_action='cancel' and v_po.status in ('draft','submitted','approved') then v_next='cancelled'; else raise exception 'invalid_purchase_order_transition'; end if; update public.mme_purchase_orders set status=v_next,ordered_at=case when v_next='submitted' then now() else ordered_at end,approved_by_auth_user_id=case when v_next='approved' then p_actor else approved_by_auth_user_id end,approved_at=case when v_next='approved' then now() else approved_at end,updated_at=now() where po_id=p_po_id; insert into public.mme_purchase_order_events(po_id,event_type,from_status,to_status,actor_auth_user_id) values(p_po_id,p_action,v_po.status,v_next,p_actor); return p_po_id; end $$;
create or replace function public.mme_purchase_order_receive_line(p_line_id uuid,p_quantity numeric,p_reference text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_line public.mme_purchase_order_lines%rowtype;v_po public.mme_purchase_orders%rowtype;v_movement uuid;v_status text;begin if p_quantity<=0 then raise exception 'invalid_receipt_quantity';end if;select * into v_line from public.mme_purchase_order_lines where line_id=p_line_id for update;if not found then raise exception 'purchase_order_line_not_found';end if;select * into v_po from public.mme_purchase_orders where po_id=v_line.po_id for update;if v_po.status not in ('approved','partially_received') then raise exception 'purchase_order_not_receivable';end if;if v_line.received_quantity+p_quantity>v_line.ordered_quantity then raise exception 'receipt_exceeds_open_quantity';end if;perform 1 from public.mme_inventory_products where product_id=v_line.product_id and is_active for update;if not found then raise exception 'active_product_not_found';end if;insert into public.mme_inventory_balances(product_id,location_id,quantity) values(v_line.product_id,v_po.location_id,0) on conflict(product_id,location_id) do nothing;update public.mme_inventory_balances set quantity=quantity+p_quantity,updated_at=now() where product_id=v_line.product_id and location_id=v_po.location_id;insert into public.mme_inventory_movements(product_id,location_id,movement_type,quantity_delta,unit_cost,reference_type,reference_id,notes,actor_auth_user_id) values(v_line.product_id,v_po.location_id,'receipt',p_quantity,v_line.unit_cost,'purchase_order',v_po.po_number||':'||coalesce(p_reference,''),'PO receiving',p_actor) returning movement_id into v_movement;update public.mme_purchase_order_lines set received_quantity=received_quantity+p_quantity where line_id=p_line_id; if exists(select 1 from public.mme_purchase_order_lines where po_id=v_po.po_id and received_quantity<ordered_quantity) then v_status='partially_received';else v_status='received';end if;update public.mme_purchase_orders set status=v_status,updated_at=now() where po_id=v_po.po_id;insert into public.mme_purchase_order_events(po_id,event_type,from_status,to_status,details,actor_auth_user_id) values(v_po.po_id,'receive',v_po.status,v_status,jsonb_build_object('line_id',p_line_id,'quantity',p_quantity,'movement_id',v_movement),p_actor);return v_movement;end $$;
alter table public.mme_vendors enable row level security;alter table public.mme_vendor_contacts enable row level security;alter table public.mme_purchase_orders enable row level security;alter table public.mme_purchase_order_lines enable row level security;alter table public.mme_vendor_invoices enable row level security;alter table public.mme_purchase_order_events enable row level security;
do $$ declare t text;begin foreach t in array array['mme_vendors','mme_vendor_contacts','mme_purchase_orders','mme_purchase_order_lines','mme_vendor_invoices','mme_purchase_order_events'] loop execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
revoke all on function public.mme_purchase_order_transition(uuid,text,uuid) from public,anon,authenticated;revoke all on function public.mme_purchase_order_receive_line(uuid,numeric,text,uuid) from public,anon,authenticated;grant execute on function public.mme_purchase_order_transition(uuid,text,uuid) to service_role;grant execute on function public.mme_purchase_order_receive_line(uuid,numeric,text,uuid) to service_role;
commit;